/**
 * NBD — Deal Room customer page script (external, CSP-strict).
 *
 * The shareable deal page (/deal/<token>, generated by
 * docs/pro/js/close-board.js) used to carry its logic in an inline
 * <script> plus inline onclick/ondrop-style handler attributes. The
 * production CSP (script-src-elem 'self' …, script-src-attr 'none')
 * blocks BOTH — the customer-facing tier picker, financing options,
 * signature pad, and ACCEPT & SCHEDULE submit were inert when served
 * first-party. This file is that logic, externalized:
 *
 *   - Config (tier prices, financing rates) rides in a JSON data island:
 *     <script type="application/json" id="nbd-deal-data"> — data blocks
 *     are not executable script, so CSP does not apply to them.
 *   - The accept token + submit URL arrive as <meta name="nbd-deal-token">
 *     / <meta name="nbd-deal-submit"> injected by getDealRoom at serve
 *     time (functions/deal-acceptance.js). The legacy window.__NBD_DEAL_*
 *     globals are still read as a fallback for non-CSP serving paths.
 *   - All interaction is data-attribute delegation: [data-deal-tier],
 *     [data-deal-action], .finance-opt[data-idx]. No inline handlers.
 *
 * Loaded via an absolute URL (https://nobigdealwithjoedeal.com/pro/
 * deal-room.js) so the same generated HTML also works when previewed
 * from a blob: URL or the raw Storage download link.
 */

(function () {
'use strict';

let CONFIG = { prices: {}, rates: [] };
try {
  const island = document.getElementById('nbd-deal-data');
  if (island) CONFIG = JSON.parse(island.textContent);
} catch (e) { /* leave defaults; page degrades to static view */ }

let selectedTier = null;
let selectedFinance = null;
let sigDrawing = false;
let sigHasContent = false;

function formatCurrency(n) {
  return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function checkReady() {
  const btn = document.getElementById('submitBtn');
  if (btn) btn.disabled = !(selectedTier && sigHasContent);
}

function selectTier(tier) {
  selectedTier = tier;
  document.querySelectorAll('.tier').forEach(t => t.classList.remove('selected'));
  const el = document.getElementById('tier-' + tier);
  if (el) el.classList.add('selected');
  updateFinancing();
  checkReady();
}

function updateFinancing() {
  const container = document.getElementById('financeOpts');
  if (!container || !selectedTier) return;
  const price = CONFIG.prices[selectedTier];
  const rates = CONFIG.rates || [];
  container.innerHTML =
    '<div class="finance-opt selected" data-idx="-1"><span class="finance-label">💰 Pay in Full</span><span class="finance-payment">' + formatCurrency(price) + '</span></div>' +
    rates.map(function (r, i) {
      const monthly = r.rate === 0
        ? price / r.term
        : price * (r.rate / 100 / 12) * Math.pow(1 + r.rate / 100 / 12, r.term) / (Math.pow(1 + r.rate / 100 / 12, r.term) - 1);
      return '<div class="finance-opt" data-idx="' + i + '"><span class="finance-label">' + r.label + '</span><span class="finance-payment">' + formatCurrency(monthly) + '/mo</span></div>';
    }).join('');
  selectedFinance = -1;
}

function selectFinancing(idx, el) {
  document.querySelectorAll('.finance-opt').forEach(o => o.classList.remove('selected'));
  if (el) el.classList.add('selected');
  selectedFinance = idx;
  checkReady();
}

// ── Signature pad ─────────────────────────────────────────────
const canvas = document.getElementById('sigCanvas');
const ctx = canvas ? canvas.getContext('2d') : null;
if (canvas && ctx) {
  canvas.width = canvas.offsetWidth * 2;
  canvas.height = canvas.offsetHeight * 2;
  ctx.scale(2, 2);
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';

  const getPos = function (e) {
    const rect = canvas.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: t.clientX - rect.left, y: t.clientY - rect.top };
  };
  canvas.addEventListener('mousedown', e => { sigDrawing = true; ctx.beginPath(); const p = getPos(e); ctx.moveTo(p.x, p.y); });
  canvas.addEventListener('mousemove', e => { if (!sigDrawing) return; const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); sigHasContent = true; checkReady(); });
  canvas.addEventListener('mouseup', () => { sigDrawing = false; });
  canvas.addEventListener('touchstart', e => { e.preventDefault(); sigDrawing = true; ctx.beginPath(); const p = getPos(e); ctx.moveTo(p.x, p.y); }, { passive: false });
  canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!sigDrawing) return; const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); sigHasContent = true; checkReady(); }, { passive: false });
  canvas.addEventListener('touchend', () => { sigDrawing = false; });
}

function clearSig() {
  if (!canvas || !ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  sigHasContent = false;
  checkReady();
}

function readMeta(name) {
  const m = document.querySelector('meta[name="' + name + '"]');
  return m ? m.content : null;
}

async function submitDeal() {
  if (!selectedTier || !sigHasContent || !canvas) return;
  const sigData = canvas.toDataURL('image/png');
  const schedDate = (document.getElementById('schedDate') || {}).value || '';
  const btn = document.getElementById('submitBtn');
  // Served via /deal/<token>: getDealRoom injects the token + same-origin
  // submit URL as meta tags (CSP-safe). Legacy window globals kept as a
  // fallback for serving paths without the strict CSP. No token = the
  // rep's in-app preview → visual walkthrough only.
  const token = readMeta('nbd-deal-token') || window.__NBD_DEAL_TOKEN;
  const url = readMeta('nbd-deal-submit') || window.__NBD_DEAL_SUBMIT_URL;
  if (token && url) {
    const orig = btn.textContent; btn.disabled = true; btn.textContent = 'Submitting...';
    try {
      const r = await fetch(url, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: token, tier: selectedTier, financing: selectedFinance, signature: sigData, scheduledDate: schedDate })
      });
      if (!r.ok) {
        const j = await r.json().catch(function () { return {}; });
        btn.disabled = false; btn.textContent = orig;
        alert((j && j.error) || 'Could not submit your acceptance. Please try again.');
        return;
      }
    } catch (e) {
      btn.disabled = false; btn.textContent = orig;
      alert('Network error. Please check your connection and try again.');
      return;
    }
  }
  const overlay = document.getElementById('successOverlay');
  if (overlay) overlay.classList.add('show');
}

// ── Time on page (2026-10-02): "12 min read" on the rep's Close Board ──
// Counts only while the page is visible; reports on hide / close with
// sendBeacon (survives the tab closing). Served via /deal/<token> only — the
// rep's in-app preview has no token and reports nothing.
(function () {
  const token = readMeta('nbd-deal-token') || window.__NBD_DEAL_TOKEN;
  const url = readMeta('nbd-deal-read');
  if (!token || !url || !navigator.sendBeacon) return;
  let visibleSince = document.visibilityState === 'visible' ? Date.now() : 0;
  let pending = 0;
  function flush() {
    if (visibleSince) { pending += (Date.now() - visibleSince) / 1000; visibleSince = 0; }
    const seconds = Math.floor(pending);
    if (seconds < 3) return;
    pending -= seconds;
    try { navigator.sendBeacon(url, new Blob([JSON.stringify({ token: token, seconds: seconds })], { type: 'text/plain' })); } catch (e) { /* best effort */ }
  }
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') flush();
    else visibleSince = Date.now();
  });
  window.addEventListener('pagehide', flush);
})();

// ── Delegated interactions (replaces the CSP-dead inline handlers) ──
document.addEventListener('click', function (ev) {
  const tier = ev.target.closest && ev.target.closest('[data-deal-tier]');
  if (tier) { selectTier(tier.dataset.dealTier); return; }
  const fin = ev.target.closest && ev.target.closest('.finance-opt[data-idx]');
  if (fin) { selectFinancing(parseInt(fin.dataset.idx, 10), fin); return; }
  const act = ev.target.closest && ev.target.closest('[data-deal-action]');
  if (!act) return;
  if (act.dataset.dealAction === 'clearSig') clearSig();
  else if (act.dataset.dealAction === 'submit') submitDeal();
});

})();
